const RECENT_KEY = 'alpha-admin-emoji-recent.v1';
const RECENT_MAX = 36;

/** @returns {string[]} */
export function recentEmojis() {
	if (typeof localStorage === 'undefined') return [];
	try {
		const raw = localStorage.getItem(RECENT_KEY);
		const parsed = raw ? JSON.parse(raw) : [];
		return Array.isArray(parsed) ? parsed.filter((x) => typeof x === 'string') : [];
	} catch {
		return [];
	}
}

/** @param {string} glyph */
export function rememberEmoji(glyph) {
	if (!glyph || typeof localStorage === 'undefined') return;
	const next = [glyph, ...recentEmojis().filter((g) => g !== glyph)].slice(0, RECENT_MAX);
	try {
		localStorage.setItem(RECENT_KEY, JSON.stringify(next));
	} catch {
		/* ignore */
	}
}

/** Flat catalog (cached). @type {EmojiItem[] | null} */
let flatCache = null;

/** @returns {EmojiItem[]} */
function allEmojis() {
	if (flatCache) return flatCache;
	/** @type {EmojiItem[]} */
	const out = [];
	for (const cat of EMOJI_CATEGORIES) {
		for (const item of cat.items) out.push(item);
	}
	flatCache = out;
	return out;
}

/**
 * Default panel list: recently used, then smileys fill.
 * @param {number} [limit]
 * @returns {EmojiItem[]}
 */
export function defaultEmojiPanel(limit = 64) {
	const byGlyph = new Map(allEmojis().map((item) => [item.g, item]));
	/** @type {EmojiItem[]} */
	const out = [];
	const seen = new Set();
	for (const g of recentEmojis()) {
		const item = byGlyph.get(g);
		if (!item || seen.has(g)) continue;
		seen.add(g);
		out.push(item);
		if (out.length >= limit) return out;
	}
	const smileys = EMOJI_CATEGORIES.find((c) => c.id === 'smileys')?.items ?? EMOJI_CATEGORIES[0]?.items ?? [];
	for (const item of smileys) {
		if (seen.has(item.g)) continue;
		seen.add(item.g);
		out.push(item);
		if (out.length >= limit) break;
	}
	return out;
}

/**
 * Ranked search — name/keyword prefix preferred over loose includes.
 * @param {string} query
 * @param {number} [limit]
 * @returns {EmojiItem[]}
 */
export function searchEmojis(query, limit = 80) {
	const q = query.trim().toLowerCase().replace(/^:/, '');
	if (!q) return defaultEmojiPanel(limit);

	/** @type {{ item: EmojiItem, score: number }[]} */
	const ranked = [];
	for (const item of allEmojis()) {
		const name = item.n.toLowerCase();
		const keys = item.k ?? [];
		let score = 0;
		if (name === q) score = 100;
		else if (name.startsWith(q)) score = 80;
		else if (keys.some((k) => k === q)) score = 75;
		else if (keys.some((k) => k.startsWith(q))) score = 60;
		else if (name.includes(q)) score = 40;
		else if (keys.some((k) => k.includes(q))) score = 30;
		else if (item.g.includes(q)) score = 10;
		if (score > 0) ranked.push({ item, score });
	}
	ranked.sort((a, b) => b.score - a.score || a.item.n.localeCompare(b.item.n));
	return ranked.slice(0, limit).map((r) => r.item);
}
